<script setup lang="ts">
import {computed,ref,shallowRef,watch,onUnmounted} from 'vue';
import {useApplication} from '../../application';import type {MinutesCurrent} from '../../shared/api/minutes-saved';import type {components} from '../../shared/api/generated';import {ApiError} from '../../shared/api/client';
type Settings=components['schemas']['SavedSettings'];type Item={locatorId:string;category:string;reason:string|null};type SourceTarget={kind:'BODY'|'ELEMENT';id:string;locatorId:string};
const props=defineProps<{meetingId:string;current:MinutesCurrent;locked:boolean;owner:boolean;saveSelection?:(fields:Record<string,unknown>)=>Promise<string|null>}>(),emit=defineEmits<{source:[target:SourceTarget];denied:[cause:unknown]}>(),app=useApplication();
const settings=shallowRef<Settings|null>(null),base=shallowRef<Settings|null>(null),chosen=ref<string[]>([]),error=ref(''),loading=ref(false),saving=ref(false),readReady=ref(false),page=ref(0),reasons=shallowRef<Record<string,string|null>>({});let epoch=0,readEpoch=0,controller:AbortController|null=null;
const key=(category:string,locatorId:string)=>JSON.stringify([category,locatorId]);const keys=(v:Settings|null)=>(v?.items??[]).map(x=>key(x.category,x.locator_id));
const dirty=computed(()=>!!base.value&&JSON.stringify([...keys(base.value)].sort())!==JSON.stringify([...chosen.value].sort()));
const conflict=computed(()=>dirty.value&&!!settings.value&&base.value?.exclusionRevision?.id!==settings.value.exclusionRevision?.id);
const choices=computed(()=>{const detected=props.current.sensitive.flatMap(d=>d.locatorIds.map(locatorId=>({locatorId,category:d.category}))),saved=[...(base.value?.items??[]),...(settings.value?.items??[])].map(x=>({locatorId:x.locator_id,category:x.category})),local=chosen.value.map(k=>{const [category,locatorId]=JSON.parse(k) as [string,string];return{category,locatorId};});return [...detected,...saved,...local].map(x=>({...x,key:key(x.category,x.locatorId),savedOnly:!detected.some(d=>d.category===x.category&&d.locatorId===x.locatorId)})).filter((x,i,a)=>a.findIndex(y=>y.key===x.key)===i);});
const labels:Record<string,string>={INTERNAL_BUSINESS_DATA:'内部经营数据',POLITICAL_SENSITIVE:'政治敏感内容'},all=computed(()=>choices.value.length>0&&choices.value.every(x=>chosen.value.includes(x.key))),mixed=computed(()=>!all.value&&chosen.value.length>0);
function toggleAll(checked:boolean){chosen.value=checked?choices.value.map(x=>x.key):[];}
function target(locatorId:string):SourceTarget|null{const e=props.current.evidence.find(e=>e.locator_id===locatorId);return e?.element_id?{kind:'ELEMENT',id:e.element_id,locatorId}:e?.minutes_revision_id?{kind:'BODY',id:e.minutes_revision_id,locatorId}:null;}
const previews=shallowRef<Record<string,string>>({}),previewErrors=shallowRef<Record<string,string>>({});let previewEpoch=0,previewController:AbortController|null=null;
async function loadPreviews(){const turn=++previewEpoch;previewController?.abort();previews.value={};previewErrors.value={};if(!props.owner||!app.session.current.value)return;previewController=new AbortController();const signal=previewController.signal;for(const item of choices.value.slice(page.value*20,(page.value+1)*20)){const t=target(item.locatorId);if(!t){previewErrors.value={...previewErrors.value,[item.locatorId]:'当前版本没有可读取的原文关联，原排除选择继续保留。'};continue;}try{const v=await app.minutesInspection.source(props.meetingId,t.locatorId,{kind:t.kind,id:t.id},signal);if(turn!==previewEpoch||signal.aborted)return;previews.value={...previews.value,[item.locatorId]:Array.from(v.text).slice(0,240).join('')};}catch(e){if(turn!==previewEpoch||signal.aborted)return;if(e instanceof ApiError&&[401,403].includes(e.status)){clear();emit('denied',e);return;}previewErrors.value={...previewErrors.value,[item.locatorId]:'原文暂不可读取，请重新核对。'};}}}
watch([()=>props.owner,()=>app.session.current.value?.actor.enterpriseId,()=>props.meetingId,()=>props.current.observation.revisionToken,()=>JSON.stringify(choices.value.slice(page.value*20,(page.value+1)*20).map(i=>i.key))],loadPreviews);
function source(locatorId:string){const t=target(locatorId);if(t)emit('source',t);else error.value='当前目录未提供可读取的关联原文；此排除项会继续保留，请明确核对后再移除。';}
function selectedItems():Item[]{return chosen.value.map(k=>{const [category,locatorId]=JSON.parse(k) as [string,string];return{locatorId,category,reason:reasons.value[k]??null};});}
function prepare(){if(!settings.value?.exclusionRevision||conflict.value||loading.value||!readReady.value)return null;return{sourceExclusionRevisionId:settings.value.exclusionRevision.id,items:selectedItems()};}
function adopt(v:Settings){settings.value=v;base.value=v;chosen.value=keys(v);reasons.value=Object.fromEntries(v.items.map(i=>[key(i.category,i.locator_id),i.reason]));error.value='';}
function discard(){if(saving.value)throw new Error('请先查清原保存结果。');if(settings.value)adopt(settings.value);}
function reapply(){if(!conflict.value||!settings.value||saving.value||props.locked)return;reasons.value={...Object.fromEntries(settings.value.items.map(i=>[key(i.category,i.locator_id),i.reason])),...reasons.value};base.value=settings.value;error.value='已保留本地选择，请核对完整集合后再次保存。';}
async function save(){if(props.locked||saving.value||!props.saveSelection)return false;const scope=epoch;saving.value=true;error.value='';try{if(!await load()||scope!==epoch)return false;const fields=prepare();if(!fields||props.locked){error.value='请先核对最新排除集合与版本冲突。';return false;}const submitted=JSON.stringify(fields.items),id=await props.saveSelection(fields);if(scope!==epoch)return false;if(!id){error.value='排除选择尚未确认保存，请保留本地选择并处理原操作结果。';return false;}const v=await load();if(!v||scope!==epoch)return false;const actual=v.items.map(i=>({locatorId:i.locator_id,category:i.category,reason:i.reason}));const canonical=(items:Item[])=>JSON.stringify([...items].sort((a,b)=>key(a.category,a.locatorId).localeCompare(key(b.category,b.locatorId))));if(v.exclusionRevision?.id!==id||canonical(actual)!==canonical(JSON.parse(submitted))){error.value='已收到原操作结果，但当前排除版本已变化；本地选择保留，请重新核对。';return false;}adopt(v);return true;}catch(e){if(scope===epoch)error.value=e instanceof Error?e.message:'排除选择暂不可保存';return false;}finally{if(scope===epoch)saving.value=false;}}
async function load(){const turn=++readEpoch,scope=epoch;controller?.abort();controller=new AbortController();const signal=controller.signal;loading.value=true;readReady.value=false;try{const v=await app.minutesInspection.settings(props.meetingId,signal);if(turn!==readEpoch||scope!==epoch||signal.aborted)return null;if(!base.value||!dirty.value)adopt(v);else settings.value=v;readReady.value=true;return v;}catch(e){if(turn===readEpoch&&scope===epoch&&!signal.aborted){if(e instanceof ApiError&&[401,403].includes(e.status)){clear();emit('denied',e);}else error.value=e instanceof Error?e.message:'排除设置暂不可用';}return null;}finally{if(turn===readEpoch&&scope===epoch)loading.value=false;}}
function clear(){previewEpoch++;previewController?.abort();previews.value={};previewErrors.value={};readReady.value=false;epoch++;readEpoch++;reasons.value={};controller?.abort();settings.value=null;base.value=null;chosen.value=[];error.value='';loading.value=false;saving.value=false;page.value=0;}
watch(()=>[props.meetingId,app.session.current.value?.actor.enterpriseId,props.owner],()=>{clear();if(props.owner&&app.session.current.value){void load();void loadPreviews();}},{immediate:true,flush:'sync'});
watch(()=>props.current.observation.revisionToken,()=>{if(props.owner&&app.session.current.value)void load();});onUnmounted(clear);defineExpose({prepare,dirty,save,discard});
</script>
<template><section id="minutes-category-SENSITIVE" class="minutes-elements sensitive-section"><div class="between"><h3>敏感信息</h3><label v-if="owner" class="select-all"><input type="checkbox" :checked="all" :indeterminate="mixed" :disabled="locked||loading||saving||!choices.length" @change="toggleAll(($event.target as HTMLInputElement).checked)"/>全部排除</label></div><p class="small muted">以下内容可能涉及内部经营数据或敏感信息，勾选并保存后不参与后续纪要生成。</p><p v-if="error" role="alert">{{error}} <button class="btn sm" :disabled="loading||saving" @click="load">重新读取排除设置</button></p><div v-if="conflict" class="banner warning" role="alert">服务器的排除集合已变化，本地选择已保留。请核对后决定。<button class="btn sm" :disabled="locked||saving||loading" @click="reapply">保留选择并应用到最新版本</button><button class="btn sm" :disabled="saving||loading" @click="discard">放弃本地选择</button></div><article v-for="item in choices.slice(page*20,(page+1)*20)" :key="item.key" class="sensitive-item"><span class="tag amber">{{labels[item.category]??item.category}}</span><p v-if="previews[item.locatorId]" class="sensitive-excerpt">{{previews[item.locatorId]}}</p><p v-else class="small muted">{{owner?(previewErrors[item.locatorId]??'正在读取已确认转写原文…'):'原文仅对会议负责人开放。'}}</p><span class="small muted">转写来源 {{choices.indexOf(item)+1}}</span><p v-if="item.savedOnly" class="small muted">当前检测目录未列出此来源，已保存的排除选择继续保留；取消勾选会明确移除此项。</p><button class="am-source-tag" @click="source(item.locatorId)">查看已确认转写原文</button><label v-if="owner"><input v-model="chosen" type="checkbox" :value="item.key" :disabled="locked||loading||saving"/>排除</label></article><p v-if="!choices.length" class="empty small">暂未识别出相关内容，请核对会议文件与背景材料。</p><div v-if="choices.length>20" class="flex"><button class="btn sm" :disabled="page===0" @click="page--">上一页</button><button class="btn sm" :disabled="(page+1)*20>=choices.length" @click="page++">下一页</button></div><div v-if="owner&&choices.length" class="between mt12"><span class="small muted">{{chosen.length}}段选择排除 · 更改后需重新生成并采用</span><button class="btn sm" :disabled="locked||loading||saving||!settings?.exclusionRevision||conflict" @click="save">保存排除选择</button></div></section></template>
<style scoped>.sensitive-section{padding:0 0 16px}.sensitive-section h3{font-size:16px;color:var(--navy)}.select-all{display:flex;gap:6px;align-items:center;font-size:12px}.sensitive-section>.small{margin:12px 0}.sensitive-item{position:relative;background:#fafafa;border-radius:6px;padding:12px 14px;margin:8px 0}.sensitive-item p{margin-top:8px}.sensitive-item>label{position:absolute;right:14px;top:14px;display:flex;gap:6px;align-items:center;font-size:12px}.am-source-tag{margin-top:8px;background:#eef3ff;border:1px solid #cbd9ff;color:var(--blue);border-radius:3px;padding:3px 7px;font-size:12px;cursor:pointer}.muted{color:var(--muted)}.sensitive-section [role=alert]{color:#9a3412}</style>
